/**
 * @name Command injection via os.system or subprocess
 * @description User-controlled data flowing into command execution can lead to arbitrary command execution
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Match os.system(command) calls
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    ) or
    // Match subprocess.call(args) calls  
    exists(API::CallNode call |
      call = API::moduleImport("subprocess").getMember(["call", "run", "Popen"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal vulnerability
 * @description User-controlled input flowing into file system operations could lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File open operations
    exists(API::CallNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      sink = call.getArg(0)
    ) or
    // os.path operations
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember(["open", "chdir", "remove", "unlink", "rename", "stat"]).getACall() and
      sink = call.getArg(0)
    ) or
    // shutil operations  
    exists(API::CallNode call |
      call = API::moduleImport("shutil").getMember(["copy", "move", "rmtree"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source.getNode(), "user input"

/**
 * @name AWS credential exposure in logs or error messages
 * @description AWS credentials or sensitive tokens being exposed in logs, error messages, or debugging output
 * @kind path-problem
 * @problem.severity error
 * @id py/aws-credential-exposure
 * @tags security
 *        external/cwe/cwe-532
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module CredentialExposureConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Look for AWS credential sources
    source instanceof RemoteFlowSource or
    exists(API::CallNode call |
      call = API::moduleImport("boto3").getMember("client").getACall() and
      source = call.getArg(1)  // aws_access_key_id parameter
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("boto3").getMember("client").getACall() and
      source = call.getArg(2)  // aws_secret_access_key parameter
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("boto3").getMember("Session").getACall() and
      source = call.getArg(1)  // aws_access_key_id parameter
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Sinks where credentials could be exposed
    exists(API::CallNode call |
      call = API::moduleImport("logging").getMember(["debug", "info", "warning", "error"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("print").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("sys").getMember("stderr").getMember("write").getACall() and
      sink = call.getArg(0)
    )
  }
}

module CredentialExposureFlow = TaintTracking::Global<CredentialExposureConfig>;
import CredentialExposureFlow::PathGraph

from CredentialExposureFlow::PathNode source, CredentialExposureFlow::PathNode sink
where CredentialExposureFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "AWS credential exposure from $@.", source.getNode(), "credential source"

/**
 * @name SSRF in boto3 HTTP requests
 * @description User-controlled data flowing into HTTP request URLs can lead to SSRF attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/ssrf
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SsrfConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for HTTP request construction with user-controlled URLs
    // boto3 uses botocore for HTTP requests, but we can look for URL construction
    // or socket connections that could be SSRF vectors
    exists(API::CallNode call |
      // Look for requests library calls
      call = API::moduleImport("requests").getMember(["get", "post", "put", "delete", "head", "patch"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // Look for urllib/urllib2/urllib3 calls
      call = API::moduleImport("urllib").getMember(["request", "urlopen"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("urllib2").getMember(["urlopen"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("urllib3").getMember(["request"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // Socket connections
      call = API::moduleImport("socket").getMember(["connect", "connect_ex"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module SsrfFlow = TaintTracking::Global<SsrfConfig>;
import SsrfFlow::PathGraph

from SsrfFlow::PathNode source, SsrfFlow::PathNode sink
where SsrfFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SSRF vulnerability from $@.", source.getNode(), "user input"

